SELECT id, employee_id, task_id, start_time, end_time, work_description, created_at
FROM time_records
WHERE id = #{id}


SELECT id, employee_id, task_id, start_time, end_time, work_description, created_at
FROM time_records
WHERE employee_id = #{employeeId}
  AND start_time >= #{from}
  AND end_time <= #{to}
ORDER BY start_time
